/* ══════════════════════════════════════════════════
   DAH 설문지 앱 — React 앱 로직
   원래 survey.html 안에 <script> 태그로 내장되어 있던
   실제 설문지 앱 코드(React.createElement 방식, JSX 아님)를
   분리한 파일입니다. React/ReactDOM 라이브러리 자체는
   특수 빌드(next 버전)라 안전을 위해 HTML에 그대로 둡니다.
   ══════════════════════════════════════════════════ */

const { useState, useCallback } = React;

// ═══════════════════════════════════════════
// 디자인 토큰 — 대시보드 완전 통일
// ═══════════════════════════════════════════
